import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Download, Search, Plus, Refresh } from '@element-plus/icons-vue'
import { usersApi, driversApi, ordersApi, marketingApi, workOrdersApi, statisticsApi, riskApi, logsApi } from '../../api/modules'
import { text, pageData } from '../../utils/format'
import BusinessFormDialog from '../../components/BusinessFormDialog.vue'
import WorkOrderEvidenceList from '../../components/WorkOrderEvidenceList.vue'

const route = useRoute(); const router = useRouter(); const loading = ref(false); const rows = ref([]); const total = ref(0); const page = ref(1); const pageSize = ref(20); const detail = ref(null); const dialog = ref(false); const dialogType = ref(''); const dialogRecord = ref({}); const submitting = ref(false); const evidenceRefreshKey = ref(0); const downloading = ref(false); const userHistoryTab = ref('orders'); const userHistoryRows = ref([]); const userHistoryTotal = ref(0); const userHistoryPage = ref(1); const userHistoryStatus = ref(undefined); const userHistoryLoading = ref(false)
const filterState = reactive({})
const title = computed(() => route.meta.title || '工作台');
const kind = computed(() => route.path.split('/')[1] || 'dashboard');
// routeKey 用完整静态路径区分普通订单与异常订单，避免被首段 orders 误判。
const routeKey = computed(() => route.path === '/orders/abnormal' ? 'orders/abnormal' : kind.value)
// filters 按路由保存筛选值，避免不同列表复用 status 等同名字段而发生条件串用。
const filters = computed(() => {
  if (!filterState[routeKey.value]) filterState[routeKey.value] = {}
  return filterState[routeKey.value]
})
const isAbnormalOrders = computed(() => routeKey.value === 'orders/abnormal')
const isStatistics = computed(() => kind.value === 'statistics')
const isDetail = computed(() => !!route.params.id || !!route.params.taskNo)
const columns = computed(() => {
  const map = {
