    'risk-hits': [['id','记录号'],['target_type','目标类型'],['target_id','目标 ID'],['scene','场景'],['risk_level','风险等级'],['hit_reason','命中原因'],['created_at','时间']],
    'operation-logs': [['id','日志号'],['admin_id','管理员'],['module','模块'],['action','动作'],['target_type','目标'],['detail','详情'],['created_at','时间']],
  }
