  orders: [{ key: 'keyword', type: 'text', placeholder: '订单号' }, { key: 'status', type: 'select', placeholder: '订单状态', options: [[1, '待接单'], [2, '已接单'], [3, '行程中'], [4, '待支付'], [5, '已完成'], [6, '已取消']] }, { key: 'user_id', type: 'number', placeholder: '用户 ID' }, { key: 'driver_id', type: 'number', placeholder: '司机 ID' }, { key: 'date_range', type: 'date-range', placeholder: '下单时间' }],
  'orders/abnormal': [{ key: 'keyword', type: 'text', placeholder: '订单号' }, { key: 'abnormal_type', type: 'select', placeholder: '异常类型', options: [['cancel', '取消异常'], ['payment', '支付异常'], ['dispatch', '派单异常']] }, { key: 'user_id', type: 'number', placeholder: '用户 ID' }, { key: 'driver_id', type: 'number', placeholder: '司机 ID' }, { key: 'date_range', type: 'date-range', placeholder: '下单时间' }],
  coupons: [{ key: 'keyword', type: 'text', placeholder: '优惠券名称' }, { key: 'type', type: 'select', placeholder: '优惠券类型', options: [[1, '满减券'], [2, '折扣券'], [3, '立减券']] }, { key: 'status', type: 'select', placeholder: '优惠券状态', options: [[1, '草稿'], [2, '启用'], [3, '停用']] }, { key: 'date_range', type: 'date-range', placeholder: '创建时间' }],
  'coupon-issue-tasks': [{ key: 'coupon_id', type: 'number', placeholder: '优惠券 ID' }, { key: 'status', type: 'select', placeholder: '任务状态', options: [['pending', '待执行'], ['processing', '执行中'], ['success', '成功'], ['failed', '失败']] }, { key: 'date_range', type: 'date-range', placeholder: '创建时间' }],
  'price-rules': [{ key: 'keyword', type: 'text', placeholder: '规则名称' }, { key: 'city_code', type: 'text', placeholder: '城市编码' }, { key: 'car_type', type: 'number', placeholder: '车型' }, { key: 'status', type: 'select', placeholder: '规则状态', options: [[1, '启用'], [2, '停用']] }],
  'work-orders': [{ key: 'status', type: 'select', placeholder: '工单状态', options: [[1, '待处理'], [2, '处理中'], [3, '已仲裁'], [4, '已关闭']] }, { key: 'assignee_id', type: 'number', placeholder: '处理人 ID' }, { key: 'work_order_type', type: 'select', placeholder: '工单类型', options: [[1, '投诉'], [2, '申诉'], [3, '其他']] }],
  'operation-logs': [{ key: 'admin_id', type: 'number', placeholder: '管理员 ID' }, { key: 'module', type: 'text', placeholder: '模块名' }, { key: 'action', type: 'text', placeholder: '操作动作' }, { key: 'target_type', type: 'text', placeholder: '目标类型' }, { key: 'target_id', type: 'number', placeholder: '目标 ID' }, { key: 'date_range', type: 'date-range', placeholder: '操作时间' }],
  'risk-hits': [{ key: 'target_type', type: 'select', placeholder: '目标对象', options: [['user', '用户'], ['driver', '司机'], ['device', '设备'], ['phone', '手机号']] }, { key: 'target_id', type: 'number', placeholder: '目标 ID' }, { key: 'scene', type: 'text', placeholder: '场景，如 login' }, { key: 'risk_level', type: 'select', placeholder: '风险等级', options: [[1, '低风险'], [2, '中风险'], [3, '高风险']] }],
  blacklist: [{ key: 'target_type', type: 'select', placeholder: '目标类型', options: [['user', '用户'], ['driver', '司机'], ['device', '设备'], ['phone', '手机号']] }, { key: 'target_id', type: 'number', placeholder: '目标 ID' }, { key: 'status', type: 'select', placeholder: '状态', options: [[1, '生效'], [2, '已解除']] }],
}
const activeFilters = computed(() => filterSchemas[routeKey.value] || [])
// listParams 仅透传当前页面已有值的字段；日期控件转换为接口约定的 start_time 和 end_time。
const listParams = () => activeFilters.value.reduce((params, field) => {
  const value = filters.value[field.key]
  if (field.type === 'date-range') {
    if (Array.isArray(value) && value.length === 2) Object.assign(params, { start_time: value[0], end_time: value[1] })
  } else if (field.type === 'number') {
    // 关联 ID 未填写或不是正数时不传给后端，避免控件默认值改变查询结果。
    const numberValue = Number(value)
    if (Number.isInteger(numberValue) && numberValue > 0) params[field.key] = numberValue
  } else if (value !== '' && value !== undefined && value !== null) params[field.key] = value
  return params
}, { page: page.value, page_size: pageSize.value })
const label = (key, value) => { const maps = { status: { 1:'正常/待接单',2:'已接单/冻结',3:'行程中',4:'待支付',5:'已完成',6:'已取消' }, audit_status:{1:'待审核',2:'已通过',3:'已驳回'}, type:{1:'满减/拉新',2:'折扣',3:'立减/活动'}, risk_level:{1:'低',2:'中',3:'高'}, abnormal_type:{cancel:'取消异常',payment:'支付异常',dispatch:'派单异常'}, payment_status:{1:'待支付',2:'已支付',3:'支付异常'}, dispatch_status:{1:'待派单',2:'已派单',3:'派单异常'} }; return maps[key]?.[value] || text(value) }
const load = async () => { if (kind.value === 'dashboard' || isStatistics.value || isDetail.value) return; loading.value = true; try { const data = await api.value(listParams()); const p = pageData(data); rows.value = p.list; total.value = p.total } finally { loading.value = false } }
// reset 只清空当前列表声明的筛选字段，避免跨路由残留条件并保留其他页面的独立状态。
const reset = () => { activeFilters.value.forEach((field) => { filters.value[field.key] = field.type === 'date-range' ? [] : undefined }); page.value = 1; load() }
const loadDetail = async () => { const id = route.params.id; if (kind.value === 'users') detail.value = await usersApi.detail(id); else if (kind.value === 'driver-certifications') detail.value = await driversApi.detail(id); else if (kind.value === 'orders') detail.value = await ordersApi.detail(id); else if (kind.value === 'price-rules') detail.value = await marketingApi.priceRule(id); else if (kind.value === 'work-orders') detail.value = await workOrdersApi.detail(id); else if (kind.value === 'export-tasks') detail.value = await statisticsApi.exportDetail(route.params.taskNo); }
// loadUserHistory 按当前页签读取用户订单或优惠券历史，两个页签的分页互不影响详情主数据。
// userHistoryStatusOptions 依据当前页签使用各自的后端状态枚举，避免订单与用户券状态混用。
const userHistoryStatusOptions = computed(() => userHistoryTab.value === 'orders'
  ? [[1, '待接单'], [2, '已接单'], [3, '行程中'], [4, '待支付'], [5, '已完成'], [6, '已取消']]
  : [[1, '未使用'], [2, '已使用'], [3, '已过期'], [4, '已锁定']])
// historyStatusText 将两类历史数据的状态转换为运营人员可读的中文文本。
const historyStatusText = (status) => (userHistoryTab.value === 'orders'
  ? ({ 1: '待接单', 2: '已接单', 3: '行程中', 4: '待支付', 5: '已完成', 6: '已取消' }[status] || text(status))
  : ({ 1: '未使用', 2: '已使用', 3: '已过期', 4: '已锁定' }[status] || text(status)))
// formatUnixTime 兼容 usersvc 返回的 Unix 秒级时间戳，空值保持统一占位显示。
const formatUnixTime = (timestamp) => { const value = Number(timestamp); return Number.isFinite(value) && value > 0 ? new Date(value * 1000).toLocaleString('zh-CN', { hour12: false }) : '-' }
// couponTypeText 与 formatCents 只用于用户券历史，金额继续沿用后端分单位精度。
const couponTypeText = (type) => ({ 1: '满减券', 2: '折扣券', 3: '立减券' }[type] || text(type))
const formatCents = (cents) => { const value = Number(cents); return Number.isFinite(value) ? `¥${(value / 100).toFixed(2)}` : '-' }
const loadUserHistory = async () => { if (kind.value !== 'users' || !route.params.id) return; userHistoryLoading.value = true; try { const params = { page: userHistoryPage.value, page_size: 20 }; if (userHistoryStatus.value !== undefined) params.status = userHistoryStatus.value; const data = userHistoryTab.value === 'orders' ? await usersApi.orders(route.params.id, params) : await usersApi.coupons(route.params.id, params); const result = pageData(data); userHistoryRows.value = result.list; userHistoryTotal.value = result.total } finally { userHistoryLoading.value = false } }
const openDetail = async (row) => { const id = row.id || row.task_no; const path = kind.value === 'export-tasks' ? `/export-tasks/${id}` : `/${kind.value}/${id}`; await router.push(path) }
// action 仅记录操作类型和当前行，字段预填、校验与请求体转换全部下沉至业务表单组件。
const action = (name, row = {}) => { dialogType.value = name; dialogRecord.value = row; dialog.value = true }
const createTypes = { coupons: 'createCoupon', 'price-rules': 'createPriceRule', 'promotion-activities': 'createActivity', 'work-orders': 'createWorkOrder', blacklist: 'createBlacklist', 'export-tasks': 'createExport' }
const openCreate = () => action(createTypes[kind.value])
const dialogTitle = computed(() => ({ createCoupon: '新建优惠券模板', editCoupon: '编辑优惠券模板', issueCoupon: '发放优惠券', createPriceRule: '新建计价规则', editPriceRule: '编辑计价规则', createActivity: '新建活动', editActivity: '编辑活动', createWorkOrder: '新建工单', workOrderAction: '工单流转', workOrderEvidence: '添加工单证据', createBlacklist: '加入黑名单', createExport: '创建导出任务', freeze: '冻结用户', unfreeze: '解冻用户', approve: '审核通过', reject: '审核驳回', cancel: '取消订单', release: '解除黑名单', disableCoupon: '停用优惠券', enableRule: '启用计价规则', disableRule: '停用计价规则', publish: '发布活动', rollback: '回滚活动' }[dialogType.value] || '确认操作'))
// submitAction 只按类型调度现有接口；组件已将字段化值转换为契约要求的 payload。
const submitAction = async ({ payload, record }) => { submitting.value = true; try { const id = record?.id; const handlers = { createCoupon: () => marketingApi.createCoupon(payload), editCoupon: () => marketingApi.updateCoupon(id, payload), issueCoupon: () => marketingApi.issueCoupon(id, payload), disableCoupon: () => marketingApi.disableCoupon(id), createPriceRule: () => marketingApi.createPriceRule(payload), editPriceRule: () => marketingApi.updatePriceRule(id, payload), enableRule: () => marketingApi.enablePriceRule(id), disableRule: () => marketingApi.disablePriceRule(id), createActivity: () => marketingApi.createActivity(payload), editActivity: () => marketingApi.updateActivity(id, payload), publish: () => marketingApi.publishActivity(id, { publish_scope: 'all', target_config: '{}' }), rollback: () => marketingApi.rollbackActivity(id, { publish_scope: '', target_config: '{}' }), createWorkOrder: () => workOrdersApi.create(payload), workOrderAction: () => workOrdersApi.action(id, payload), workOrderEvidence: () => workOrdersApi.evidence(id, payload), createBlacklist: () => riskApi.add(payload), release: () => riskApi.release(id, payload), createExport: () => statisticsApi.createExport(payload), freeze: () => usersApi.freeze(id, payload), unfreeze: () => usersApi.unfreeze(id, payload), approve: () => driversApi.approve(id, payload), reject: () => driversApi.reject(id, payload), cancel: () => ordersApi.cancel(id, payload) }; await handlers[dialogType.value]?.(); if (dialogType.value === 'workOrderEvidence') evidenceRefreshKey.value += 1; dialog.value = false; ElMessage.success('操作成功'); if (isDetail.value) await loadDetail(); else await load() } finally { submitting.value = false } }
// isExportReady 兼容后端数值与文本状态，只有异步导出完成后才显示下载入口。
const isExportReady = computed(() => [2, 'completed', 'success', 'done'].includes(detail.value?.status))
// downloadExport 通过受保护的下载接口获取 CSV Blob，浏览器端只使用任务号生成文件名。
const downloadExport = async () => { downloading.value = true; try { const response = await statisticsApi.downloadExport(route.params.taskNo); const objectURL = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = objectURL; link.download = `${route.params.taskNo}.csv`; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(objectURL) } finally { downloading.value = false } }
// detailEntries 显式列出详情字段并过滤空值，防止把服务端对象直接以 JSON 暴露给运营人员。
const detailEntries = computed(() => Object.entries(detail.value || {}).filter(([key, value]) => value !== null && value !== undefined && value !== '').map(([key, value]) => ({ key, value: typeof value === 'object' ? JSON.stringify(value) : label(key, value) })))
const dashboard = ref({ overview: {}, orders: {}, coupons: {} });
const statisticsRange = ref([])
// statisticsParams 统一生成统计接口时间范围；未选择时默认近 30 天。
const statisticsParams = () => { if (statisticsRange.value?.length === 2) return { start_time: statisticsRange.value[0], end_time: statisticsRange.value[1] }; const end = new Date(); const start = new Date(end); start.setDate(end.getDate() - 30); const fmt = (d) => d.toISOString().slice(0, 19).replace('T', ' '); return { start_time: fmt(start), end_time: fmt(end) } }
// loadDashboard 并发请求三个真实统计接口，工作台和数据统计页共用同一份数据。
const loadDashboard = async () => { loading.value = true; try { const params = statisticsParams(); const [overview, orders, coupons] = await Promise.all([statisticsApi.overview(params), statisticsApi.orders(params), statisticsApi.coupons(params)]); dashboard.value = { overview: overview || {}, orders: orders || {}, coupons: coupons || {} } } finally { loading.value = false } }
onMounted(async () => { if (kind.value === 'dashboard' || isStatistics.value) return loadDashboard(); if (isDetail.value) { await loadDetail(); await loadUserHistory(); return }; await load() }); watch(() => route.path, async () => { detail.value = null; page.value = 1; userHistoryPage.value = 1; if (kind.value === 'dashboard' || isStatistics.value) return loadDashboard(); if (isDetail.value) { await loadDetail(); await loadUserHistory(); return }; await load() });
</script>

<template>
  <section class="console" v-loading="loading">
    <template v-if="kind === 'dashboard' || isStatistics">
      <div class="hero"><div><span class="eyebrow">运营数据中心</span><h1>{{ isStatistics ? '数据统计' : '工作台' }}</h1><p>{{ isStatistics ? '按时间范围查看用户、订单与营销核心指标' : '实时掌握用户、订单与营销运营状态' }}</p></div><div class="statistics-actions"><el-date-picker v-if="isStatistics" v-model="statisticsRange" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间" /><el-button :icon="Refresh" @click="loadDashboard">刷新数据</el-button></div></div>
      <div class="metric-grid"><div v-for="item in [{k:'order_count',t:'订单总量'},{k:'completed_order_count',t:'完成订单'},{k:'user_count',t:'用户总量'},{k:'driver_count',t:'司机总量'},{k:'gmv',t:'GMV'}]" :key="item.k" class="metric"><span>{{ item.t }}</span><strong>{{ text(dashboard.overview[item.k]) }}</strong><small>来自实时统计接口</small></div></div>
      <div class="panel-grid"><div class="panel"><div class="panel-title">订单运营</div><div class="stat-line"><span>完成率</span><b>{{ text(dashboard.orders.completion_rate) }}</b></div><div class="stat-line"><span>取消率</span><b>{{ text(dashboard.orders.cancel_rate) }}</b></div><div class="stat-line"><span>异常订单</span><b>{{ text(dashboard.overview.abnormal_order_count) }}</b></div></div><div class="panel"><div class="panel-title">优惠券运营</div><div class="stat-line"><span>优惠券模板</span><b>{{ text(dashboard.coupons.coupon_count) }}</b></div><div class="stat-line"><span>已启用</span><b>{{ text(dashboard.coupons.enabled_coupon_count) }}</b></div><div class="stat-line"><span>使用率</span><b>{{ text(dashboard.coupons.use_rate) }}</b></div></div></div>
    </template>
    <template v-else-if="isDetail"><div class="page-head"><div><span class="eyebrow">详情视图</span><h1>{{ title }}</h1></div><div class="head-actions"><el-button v-if="kind === 'work-orders'" type="primary" @click="action('workOrderAction', detail || {})">工单流转</el-button><el-button v-if="kind === 'work-orders'" @click="action('workOrderEvidence', detail || {})">添加证据</el-button><el-button v-if="kind === 'export-tasks' && isExportReady" type="primary" :icon="Download" :loading="downloading" @click="downloadExport">下载 CSV</el-button><el-button @click="router.back()">返回列表</el-button></div></div><div class="panel detail-grid"><div v-for="item in detailEntries" :key="item.key" class="detail-item"><span>{{ item.key }}</span><strong>{{ item.value }}</strong></div></div><section v-if="kind === 'users'" class="panel history-panel"><div class="history-toolbar"><el-select v-model="userHistoryStatus" clearable placeholder="全部状态" @change="userHistoryPage=1;loadUserHistory()"><el-option v-for="option in userHistoryStatusOptions" :key="option[0]" :label="option[1]" :value="option[0]" /></el-select></div><el-tabs v-model="userHistoryTab" @tab-change="userHistoryStatus=undefined;userHistoryPage=1;loadUserHistory()"><el-tab-pane label="订单历史" name="orders"><el-table :data="userHistoryRows" v-loading="userHistoryLoading"><el-table-column prop="order_no" label="订单号" /><el-table-column prop="from_address" label="出发地" /><el-table-column prop="to_address" label="目的地" /><el-table-column prop="estimated_price" label="预估金额"><template #default="scope">¥{{ text(scope.row.estimated_price) }}</template></el-table-column><el-table-column prop="status" label="状态"><template #default="scope">{{ historyStatusText(scope.row.status) }}</template></el-table-column><el-table-column prop="created_at" label="下单时间" /></el-table></el-tab-pane><el-tab-pane label="优惠券历史" name="coupons"><el-table :data="userHistoryRows" v-loading="userHistoryLoading"><el-table-column prop="name" label="优惠券" /><el-table-column prop="type" label="类型"><template #default="scope">{{ couponTypeText(scope.row.type) }}</template></el-table-column><el-table-column prop="face_value_cents" label="面值"><template #default="scope">{{ formatCents(scope.row.face_value_cents) }}</template></el-table-column><el-table-column prop="status" label="状态"><template #default="scope">{{ historyStatusText(scope.row.status) }}</template></el-table-column><el-table-column prop="received_at" label="领取时间"><template #default="scope">{{ formatUnixTime(scope.row.received_at) }}</template></el-table-column><el-table-column prop="expire_at" label="到期时间"><template #default="scope">{{ formatUnixTime(scope.row.expire_at) }}</template></el-table-column></el-table></el-tab-pane></el-tabs><el-pagination v-model:current-page="userHistoryPage" :total="userHistoryTotal" layout="prev, pager, next" @current-change="loadUserHistory" /></section><WorkOrderEvidenceList v-if="kind === 'work-orders'" :work-order-id="route.params.id" :refresh-key="evidenceRefreshKey" /></template>
    <template v-else><el-alert v-if="kind === 'drivers'" title="司机服务尚未接入，暂不能展示真实司机数据" type="info" :closable="false" show-icon style="margin-bottom:16px" />
      <div class="page-head"><div><span class="eyebrow">管理后台 / {{ title }}</span><h1>{{ title }}</h1></div><div class="head-actions"><el-button :icon="Refresh" @click="load">刷新</el-button><el-button v-if="['coupons','price-rules','promotion-activities','work-orders','blacklist','export-tasks'].includes(kind)" type="primary" :icon="Plus" @click="openCreate">新建</el-button></div></div>
      <div class="panel filters"><template v-for="field in activeFilters" :key="field.key"><el-input v-if="field.type === 'text'" v-model="filters[field.key]" :placeholder="field.placeholder" clearable :prefix-icon="field.key === 'keyword' ? Search : undefined" @keyup.enter="page=1;load" /><el-input v-else-if="field.type === 'number'" v-model="filters[field.key]" type="number" :placeholder="field.placeholder" clearable @keyup.enter="page=1;load" /><el-select v-else-if="field.type === 'select'" v-model="filters[field.key]" :placeholder="field.placeholder" clearable><el-option v-for="option in field.options" :key="option[0]" :label="option[1]" :value="option[0]" /></el-select><el-date-picker v-else-if="field.type === 'date-range'" v-model="filters[field.key]" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" :start-placeholder="`${field.placeholder}开始`" :end-placeholder="`${field.placeholder}结束`" /></template><el-button type="primary" @click="page=1;load">查询</el-button><el-button @click="reset">重置</el-button></div>
      <div class="panel table-panel"><el-table :data="rows" stripe empty-text="暂无数据"><el-table-column v-for="c in columns" :key="c[0]" :prop="c[0]" :label="c[1]" min-width="140"><template #default="scope"><span :class="{mono:c[0].includes('id') || c[0].includes('no')}" >{{ label(c[0], scope.row[c[0]]) }}</span></template></el-table-column><el-table-column label="操作" fixed="right" width="320"><template #default="scope"><el-button link type="primary" @click="openDetail(scope.row)">查看</el-button><el-button v-if="kind==='users'" link type="warning" @click="action(scope.row.status==1?'freeze':'unfreeze',scope.row)">{{ scope.row.status==1?'冻结':'解冻' }}</el-button><el-button v-if="kind==='driver-certifications' && scope.row.audit_status==1" link type="success" @click="action('approve',scope.row)">通过</el-button><el-button v-if="kind==='driver-certifications' && scope.row.audit_status==1" link type="danger" @click="action('reject',scope.row)">驳回</el-button><el-button v-if="kind==='orders' && !isAbnormalOrders && ![5,6].includes(scope.row.status)" link type="danger" @click="action('cancel',scope.row)">取消订单</el-button><el-button v-if="kind==='coupons'" link type="primary" @click="action('editCoupon',scope.row)">编辑</el-button><el-button v-if="kind==='coupons' && scope.row.status!=3" link type="success" @click="action('issueCoupon',scope.row)">发券</el-button><el-button v-if="kind==='coupons' && scope.row.status!=3" link type="warning" @click="action('disableCoupon',scope.row)">停用</el-button><el-button v-if="kind==='blacklist' && scope.row.status==1" link type="danger" @click="action('release',scope.row)">解除</el-button><el-button v-if="kind==='price-rules'" link type="primary" @click="action('editPriceRule',scope.row)">编辑</el-button><el-button v-if="kind==='price-rules'" link type="success" @click="action(scope.row.status==2?'disableRule':'enableRule',scope.row)">{{scope.row.status==2?'停用':'启用'}}</el-button><el-button v-if="kind==='promotion-activities'" link type="primary" @click="action('editActivity',scope.row)">编辑</el-button><el-button v-if="kind==='promotion-activities'" link type="warning" @click="action(scope.row.status==2?'rollback':'publish',scope.row)">{{scope.row.status==2?'回滚':'发布'}}</el-button></template></el-table-column></el-table><div class="table-footer"><span>共 {{ total }} 条记录</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" layout="prev, pager, next, sizes" @current-change="load" @size-change="load" /></div></div>
    </template>
    <BusinessFormDialog v-model="dialog" :type="dialogType" :title="dialogTitle" :record="dialogRecord" :loading="submitting" @submit="submitAction" />
  </section>
</template>

